const ExyokiOffice::OpenXMLElementClass* OpenXmlElementFactory::ResolveClass(const ExyokiOffice::OpenXmlQualifiedName& name)
{
    const auto it = std::lower_bound(kElementEntries.begin(),
                                         kElementEntries.end(),
                                         name,
                                         [](const ElementEntry& entry, const ExyokiOffice::OpenXmlQualifiedName& value) {
                                             return entry.Name < value;
                                         });
    if (it != kElementEntries.end() && it->Name == name)
    {
        return it->MetaClass;
    }
    return nullptr;
}

std::shared_ptr<ExyokiOffice::OpenXMLElement> OpenXmlElementFactory::Create(const ExyokiOffice::OpenXmlQualifiedName& name)
{
    if (const auto* metaClass = ResolveClass(name))
    {
        auto instance = metaClass->Create();
        if (instance)
        {
            return instance;
        }
    }
    return nullptr;
}

bool OpenXmlElementFactory::IsAmbiguousElementName(const ExyokiOffice::OpenXmlQualifiedName& name)
{
    return std::binary_search(kAmbiguousElementNames.begin(), kAmbiguousElementNames.end(), name);
}

const ExyokiOffice::OpenXMLElementClass* OpenXmlElementFactory::ResolveClassByTypeName(std::string_view qualifiedTypeName)
{
    const auto it = std::lower_bound(kTypeNameEntries.begin(),
                                     kTypeNameEntries.end(),
                                     qualifiedTypeName,
                                     [](const TypeNameEntry& entry, std::string_view value) {
                                         return entry.TypeName < value;
                                     });
    if (it != kTypeNameEntries.end() && it->TypeName == qualifiedTypeName)
    {
        return it->MetaClass;
    }
    return nullptr;
}

std::span<const ExyokiOffice::OpenXMLElementClass* const> OpenXmlElementFactory::AllElementClasses()
{
    return kAllElementClasses;
}
